const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const kerala = ee.Geometry.Polygon([
    [[74.8, 8.2], [77.5, 8.2], [77.5, 12.8], [74.8, 12.8], [74.8, 8.2]]
  ]);

  const sriLanka = ee.Geometry.Polygon([
    [[79.5, 5.9], [82.0, 5.9], [82.0, 9.9], [79.5, 9.9], [79.5, 5.9]]
  ]);

  const startDate = '2018-07-01';
  const endDate = '2018-08-31';

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  const collectionSize = chirps.size().getInfo();
  console.log(`CHIRPS Images Found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No CHIRPS data available for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum total rainfall
  const totalRainfall = chirps.select('precipitation').sum();

  // 4. Calculate rainfall for both regions
  const keralaStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: kerala,
    scale: 5000,
    maxPixels: 1e9
  });

  const sriLankaStats = totalRainfall.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: sriLanka,
    scale: 5000,
    maxPixels: 1e9
  });

  const keralaRainfall = keralaStats.get('precipitation').getInfo();
  const sriLankaRainfall = sriLankaStats.get('precipitation').getInfo();

  // Check pixel counts
  const keralaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: kerala,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const sriLankaCount = totalRainfall.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sriLanka,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Kerala: ${keralaRainfall !== null ? keralaRainfall.toFixed(2) : 'null'} mm (Pixels: ${keralaCount})`);
  console.log(`Sri Lanka: ${sriLankaRainfall !== null ? sriLankaRainfall.toFixed(2) : 'null'} mm (Pixels: ${sriLankaCount})`);

  // 5. Validation & Final Answer
  if (keralaCount === 0 || sriLankaCount === 0) {
    console.log("No valid pixels found.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (keralaRainfall === null || sriLankaRainfall === null || 
      isNaN(keralaRainfall) || isNaN(sriLankaRainfall) ||
      keralaRainfall < 0 || sriLankaRainfall < 0) {
    console.log("Invalid calculation result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (keralaRainfall > sriLankaRainfall) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
